import sys, json, re, math
from datetime import datetime, timezone
LEVELS = {"DEBUG", "INFO", "WARN", "ERROR"}


def to_epoch(s):
    try:
        return int(datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc).timestamp())
    except (ValueError, TypeError):
        return None


def iso(e):
