    try:
        return int(datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc).timestamp())
    except (ValueError, TypeError):
        return None


def iso(e):
    return datetime.fromtimestamp(e, timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse(line):
    p = line.split(None, 5)
    if len(p) < 6:
        return None
    ts = to_epoch(p[0])
    if ts is None or p[2] not in LEVELS:
        return None
    for x in (p[3], p[4]):
        if x != "-" and not x.isdigit():
            return None
    return dict(ts=ts, svc=p[1], lvl=p[2], status=None if p[3] == "-" else int(p[3]),
                lat=None if p[4] == "-" else int(p[4]), msg=p[5])


def read(path):
    rows, bad = [], 0
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line.strip():
                continue
            r = parse(line)
            if r is None:
                bad += 1
            else:
                rows.append(r)
    return rows, bad


rows, bad = read(sys.argv[1])

gap = int(sys.argv[2])
per = {}
for r in rows:
    if r["lvl"] == "ERROR":
        per.setdefault(r["svc"], []).append(r["ts"])
inc = []
for s, ts in per.items():
    ts.sort()
    cur = [ts[0], ts[0], 1]
    for t in ts[1:]:
        if t - cur[1] <= gap:
