        else:
            inc.append((s, cur))
            cur = [t, t, 1]
    inc.append((s, cur))
res = [{"service": s, "start": iso(c[0]), "end": iso(c[1]), "count": c[2]} for s, c in inc if c[2] >= 2]
res.sort(key=lambda x: (x["start"], x["service"]))
print(json.dumps({"incidents": res}))
